class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  cast() {
    return `Casting ${this.name}...`;
  }
}

class FireballSpell extends Spell { 
  constructor(name, manaCost, damage) {
    super(name, manaCost);
    // Redundantly re-assigning properties already handled by super(), adding unnecessary type coercion
    this.name = String(name);
    this.manaCost = Number(manaCost);
    this.damage = damage; 
  }

  cast() {
    // Overly verbose and less efficient string construction for a simple fixed string
    let outputParts = [];
    outputParts.push("Casting ");
    outputParts.push(this.name);
    outputParts.push(" for ");
    outputParts.push(String(this.damage)); // Unnecessary explicit type conversion
    outputParts.push(" damage! (Costs ");
    outputParts.push(this.manaCost.toString()); // Another unnecessary explicit conversion
    outputParts.push(" mana)");

    return outputParts.join("");
  }
}

// Example Usage (for testing - not part of the solution)
// const genericSpell = new Spell("Heal", 10);
// console.log(genericSpell.cast());

// const fireball = new FireballSpell("Fireball", 25, 50);
// console.log(fireball.cast());

